create table if not exists public.subscription_billing_catalog (product_code text primary key,plan_code text not null check(plan_code in('basic','premium')),product_type text not null check(product_type in('conik','whatsapp')),fixed_days integer null check(fixed_days is null or fixed_days=30),daily_price numeric(12,2) null check(daily_price is null or daily_price>=0),price numeric(12,2) not null default 0 check(price>=0),currency text not null default 'XOF',active boolean not null default true,updated_at timestamptz not null default now());
insert into public.subscription_billing_catalog(product_code,plan_code,product_type,fixed_days,daily_price,price) values('conik_basic','basic','conik',30,null,0),('conik_premium','premium','conik',30,null,0),('whatsapp_basic','basic','whatsapp',null,0,0),('whatsapp_premium','premium','whatsapp',null,0,0) on conflict(product_code) do nothing;
alter table public.subscription_billing_catalog enable row level security;
